{"hypotheses": [
  {
    "name": "Intangible-Adjusted Quality-Momentum Hybrid",
    "mechanism": "Firms with strong profitability (OperProf) and high intangible investment (IntanBM), but low equity issuance (NetEquityFinance), exhibit superior sustainable growth not captured by the individual signals. Adding past return momentum (Mom12m) filters for persistent winners, compounding the effect. The joint signal isolates innovative, disciplined capital allocators with positive feedback loops between innovation and market recognition.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Defensive Volatility-Value Composite",
    "mechanism": "Stocks with high book-to-market (BM) and earnings yield (EP), but low systematic volatility (betaVIX) and idiosyncratic risk (IdioVolAHT), deliver outsized risk-adjusted returns in risk-off regimes. The composite captures risk-averse value opportunities that are shunned during periods of elevated volatility but mean revert strongly as flows favor safety and valuation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 0.5, "primitive": "EP"},
        {"weight": -0.5, "primitive": "betaVIX"},
        {"weight": -1.0, "primitive": "IdioVolAHT"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Short Interest Disagreement Spread",
    "mechanism": "A portfolio long stocks with high analyst EPS forecast dispersion (ForecastDispersion) and high short interest (ShortInterest), but low institutional ownership among shorts (IO_ShortInterest), exploits informational disagreement and constraints. Excess returns stem from limits to arbitrage preventing rapid correction of mispricings where investors disagree and shorting is expensive.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "ShortInterest"},
        {"weight": -1.0, "primitive": "IO_ShortInterest"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Quality Reversal",
    "mechanism": "Stocks with positive recent earnings surprises (EarningsSurprise) and high cash-based operating profitability (CBOperProf), but high accruals (Accruals), tend to revert as the market overreacts to low-quality earnings beats. The composite shorts ‘low-quality’ earnings beats, capturing the post-announcement drift reversal driven by accounting manipulation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "CBOperProf"},
        {"weight": -1.0, "primitive": "Accruals"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "Accruals", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "R&D-Driven Low-Leverage Growth",
    "mechanism": "Companies investing heavily in R&D (RD) and with high gross profits (GP), but with low book leverage (BookLeverage), outperform as their investment signals unique, difficult-to-replicate growth and minimal distress risk. The value-add comes from isolating innovative compounders with conservative capital structures that avoid the negative tail risks of leverage.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 0.5, "primitive": "GP"},
        {"weight": -1.0, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Post-Announcement Underreaction Quality Filter",
    "mechanism": "Stocks with strong prior earnings announcement returns (AnnouncementReturn) and high Piotroski F-scores (PS), but low bid-ask spreads (BidAskSpread), systematically underreact as the market slowly prices in positive signals from clear financial improvement in liquid names, distinct from pure announcement drift or accounting quality alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnnouncementReturn"},
        {"weight": 0.5, "primitive": "PS"},
        {"weight": -1.0, "primitive": "BidAskSpread"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "AnnouncementReturn", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Organizational Capital Franchise Compounder",
    "mechanism": "Stocks with high organizational capital (OrgCap) and high return on equity (RoE), but low external financing (XFIN), outperform as they compound capital internally and avoid dilution. The synergy captures hard-to-replicate franchise value supported by internal resource accumulation and profitable reinvestment, distinct from quality or capital structure factors alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "RoE"},
        {"weight": -1.0, "primitive": "XFIN"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "IPO Age-Momentum Anomaly",
    "mechanism": "Stocks with recent IPOs (AgeIPO), strong intermediate-term momentum (Mom6m), and high investment (Investment) but low idiosyncratic volatility (IdioVol3F), exploit the market’s underestimation of newly-listed firms’ persistence that have low lottery-like risk. The composite isolates winners among younger public firms with credible reinvestment and low speculative risk.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 0.5, "primitive": "Mom6m"},
        {"weight": 0.5, "primitive": "Investment"},
        {"weight": -1.0, "primitive": "IdioVol3F"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom6m", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 24
  }
]}
